const protocolo = $('Loop por Protocolo').item.json;
const planosCliente = $input.item.json;

const planos = Array.isArray(planosCliente) ? planosCliente : [planosCliente];

// Encontrar o plano pelo codPlano = belle_id da venda
const planoMatch = planos.find(p => String(p.codPlano) === String(protocolo.belle_id));

let sessoesRealizadas = protocolo.sessoes_realizadas || 0;
let saldoRestanteTotal = 0;
let planoEncerrado = false;

if (planoMatch && planoMatch.servicos) {
  saldoRestanteTotal = planoMatch.servicos.reduce((acc, s) => {
    return acc + (parseInt(s.saldoRestante) || 0);
  }, 0);
  sessoesRealizadas = Math.max(0, (protocolo.sessoes_total || 0) - saldoRestanteTotal);
  planoEncerrado = saldoRestanteTotal === 0;
} else if (!planoMatch) {
  // Plano não encontrado na Belle = provavelmente encerrado
  planoEncerrado = true;
  sessoesRealizadas = protocolo.sessoes_total || 0;
}

return {
  json: {
    db_id:              protocolo.id,
    belle_id:           protocolo.belle_id,
    sessoes_total:      protocolo.sessoes_total,
    sessoes_realizadas: sessoesRealizadas,
    saldo_restante:     saldoRestanteTotal,
    plano_encerrado:    planoEncerrado,
    nome_protocolo:     protocolo.nome_protocolo
  }
};

