UPDATE vendas SET
  sessoes_realizadas = {{ $json.sessoes_realizadas }},
  status_plano = CASE WHEN {{ $json.plano_encerrado ? 'TRUE' : 'FALSE' }} THEN 'Concluido' ELSE status_plano END,
  atualizado_em = NOW()
WHERE id = {{ $json.db_id }}
RETURNING id, belle_id, nome_protocolo, sessoes_total, sessoes_realizadas, status_plano;
